const $=id=>document.getElementById(id),esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
let lab=new DeskLab(),monitor=new TrainerMonitor(lab),scope=new TDS2001C(lab);lab.traceEnabled=false;
$('equipment-layer').insertAdjacentHTML('beforebegin','<svg id="back-cables" viewBox="0 0 2200 1450" aria-label="AC supply cables"></svg>');$('equipment-layer').innerHTML=sceneMarkup();applyPhotographicSkins();initializeLegibility();const screen=new TDSDisplay($('tek-screen'),scope),viewport=$('desk-viewport'),transform=$('desk-transform');
let view={x:0,y:0,scale:.6},layout=structuredClone(INITIAL_LAYOUT),pending=null,selectedWire=null,drag=null,paused=false,speed=1,lastPower=false,notebookTab='procedures',experiment='ramp',entryQueue=[],entryDue=0,caps=true,shift=false,lastHistory=-1,toastTimer,lastUi=0,lastFrame=performance.now(),currentFocus='all',lastSize={w:viewport.clientWidth,h:viewport.clientHeight};
function toast(message){$('desk-toast').textContent=message;$('desk-toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('desk-toast').classList.remove('visible'),3200);}
function guard(fn){try{return fn();}catch(error){toast(error.message);console.error(error);}}
function updateView(){updateLegibility(layout,view,lab.mapping);$('toggle-labels').setAttribute('aria-pressed',String(view.labels!==false));transform.style.transform=`translate(${view.x}px,${view.y}px) scale(${view.scale})`;$('zoom-label').textContent=Math.round(view.scale*100)+'%';}
function focus(name='all'){const rect=viewport.getBoundingClientRect(),r=name==='all'?{x:20,y:-15,w:2130,h:1440}:name==='lcd'?{x:layout.trainer.x+345,y:layout.trainer.y+473,w:411,h:128}:name==='scope-screen'?{x:layout.scope.x+76,y:layout.scope.y+98,w:350,h:236}:layout[name];if(!r)return;currentFocus=name;const pad=name==='all'?25:name==='lcd'||name==='scope-screen'?20:45;view.scale=clamp(Math.min((rect.width-pad*2)/r.w,(rect.height-pad*2)/r.h),.13,name==='lcd'?1.7:name==='scope-screen'?3:2.5);view.x=(rect.width-r.w*view.scale)/2-r.x*view.scale;view.y=(rect.height-r.h*view.scale)/2-r.y*view.scale;updateView();drawWires();}
function world(x,y){const r=viewport.getBoundingClientRect();return {x:(x-r.left-view.x)/view.scale,y:(y-r.top-view.y)/view.scale};}
function zoom(factor,x=viewport.clientWidth/2,y=viewport.clientHeight/2){currentFocus=null;const old=view.scale;view.scale=clamp(old*factor,.13,3);view.x=x-(x-view.x)*view.scale/old;view.y=y-(y-view.y)*view.scale/old;updateView();}
function findEnd(id,type){let selector;if(type==='frc'||type==='bus')selector=`[data-connector="${id}"]`;else if(type==='power')selector=`[data-connector="${id}.power"]`;else selector=`[data-terminal="${id}"]`;return document.querySelector(selector)||document.querySelector(`[data-connector="${id}"]`);}
function endPosition(id,type){const el=findEnd(id,type);if(!el)return null;const r=el.getBoundingClientRect();return world(r.left+r.width/2,r.top+r.height/2);}
function wirePath(a,b,type=''){const bend=Math.max(45,Math.min(170,Math.hypot(b.x-a.x,b.y-a.y)*.17));if(type==='bus'){if(a.y>b.y)[a,b]=[b,a];const left=Math.min(a.x,b.x)-100,top=Math.min(a.y,b.y)-140,mid=(a.y+b.y)/2;return `M${a.x} ${a.y} C${a.x-110} ${a.y} ${left} ${top} ${left} ${mid} C${left} ${b.y+70} ${b.x-65} ${b.y} ${b.x} ${b.y}`;}return `M${a.x.toFixed(1)} ${a.y.toFixed(1)} C${a.x.toFixed(1)} ${(a.y+bend).toFixed(1)} ${b.x.toFixed(1)} ${(b.y+bend).toFixed(1)} ${b.x.toFixed(1)} ${b.y.toFixed(1)}`;}
function drawWires(){updateLegibility(layout,view,lab.mapping);const parts=[],back=[];document.querySelectorAll('.connected-connector').forEach(e=>e.classList.remove('connected-connector'));for(const cable of lab.patchbay.cables){const a=endPosition(cable.a,cable.type),b=endPosition(cable.b,cable.type);if(!a||!b)continue;const path=wirePath(a,b,cable.type),selected=selectedWire===cable.id,wide=cable.type==='bus'?43:cable.type==='frc'?25:cable.type==='power'?12:cable.type==='mains'?6:cable.type==='probe'?5:3;let visible=`<path d="${path}" stroke="#17201bb0" stroke-width="${wide+3}" fill="none" transform="translate(2 5)"/><path d="${path}" stroke="${['frc','bus'].includes(cable.type)?'#b9bcb3':cable.color}" stroke-width="${wide}" fill="none"/>`;
    if(cable.type==='frc'||cable.type==='bus'){const half=cable.type==='bus'?20:10;for(let i=-half;i<=half;i+=2.3)visible+=`<path d="${wirePath({x:a.x+i,y:a.y},{x:b.x+i,y:b.y},cable.type)}" stroke="${i<-half+2?'#c87e9a':'#7a8980'}" stroke-width=".8" fill="none"/>`;}
    else if(cable.type==='power'){['#b93730','#252a25','#34846a','#dfc135'].forEach((color,i)=>{const off=(i-1.5)*3;visible+=`<path d="${wirePath({x:a.x+off,y:a.y},{x:b.x+off,y:b.y})}" stroke="${color}" stroke-width="2.5" fill="none"/>`;});}
    else visible+=`<path d="${path}" stroke="#dbe2ce33" stroke-width="1" fill="none" transform="translate(-1 -1)"/>`;
    for(const p of [a,b])visible+=['frc','bus'].includes(cable.type)?`<rect x="${p.x-18}" y="${p.y-5}" width="36" height="13" rx="2" fill="#303c34" stroke="#7a8a74"/>`:`<circle cx="${p.x}" cy="${p.y}" r="${wide>5?5:4}" fill="${cable.type==='keyboard'?'#686080':'#3b453b'}" stroke="#98a58b" stroke-width="1.5"/>`;
    (cable.type==='mains'?back:parts).push(`<g class="cable ${selected?'selected':''}" data-cable="${cable.id}" aria-label="${esc(cable.type+' '+terminalName(cable.a,lab.mapping,cable.type)+' to '+terminalName(cable.b,lab.mapping,cable.type))}"><path class="wire-highlight" d="${path}"/>${visible}<path class="wire-hit" pathLength="100" stroke-dasharray="90 100" stroke-dashoffset="-5" d="${path}"/></g>`);for(const id of [cable.a,cable.b])findEnd(id,cable.type)?.classList.add('connected-connector');}
  $('patch-cables').innerHTML=parts.join('');$('back-cables').innerHTML=back.join('');
}
function clearPending(){pending=null;$('pending-cable').innerHTML='';document.querySelectorAll('.selected-terminal').forEach(e=>e.classList.remove('selected-terminal'));$('wire-status').classList.remove('wiring');$('wire-status').textContent='Choose two connectors to attach a cable.';}
function selectTerminal(el){const choice=$('cable-type').value,connector=el.closest('[data-connector]'),pin=el.closest('[data-terminal]');let id,type,anchor;
  if(connector&&choice!=='jumper'&&choice!=='ground'&&choice!=='probe'){id=connector.dataset.connector;type=CONNECTORS[id].type;anchor=connector;}else if(pin){id=pin.dataset.terminal;type=choice==='auto'?(id.includes('scope.ch')&&id.endsWith('.tip')?'probe':id.endsWith('.gnd')?'ground':'jumper'):choice;anchor=pin;}else{toast('Choose a terminal or use Auto connector for the whole cable');return;}
  if(pending){const first=pending;clearPending();if(first.id===id)return;let finalType=choice==='auto'?(first.type==='probe'||type==='probe'?'probe':first.type==='ground'||type==='ground'?'ground':first.type):choice;
    if(['frc','bus','power','mains','keyboard'].includes(finalType)){if(first.type!==type||type!==finalType)throw new Error('Choose matching connector types, or use Jumper for individual pins');if(finalType==='frc'&&first.id.startsWith('trainer.')===id.startsWith('trainer.'))toast('Ribbon joined: check port directions before driving the bus');}
    const from=CONNECTORS[first.id]?.prefix||first.id,to=CONNECTORS[id]?.prefix||id;lab.cable(from,to,finalType,$('wire-color').value);lab.sync();drawWires();updatePower();refresh();if($('notebook').classList.contains('open')&&notebookTab==='connections')renderNotebook();toast(terminalName(first.id,lab.mapping)+' ↔ '+terminalName(id,lab.mapping));
  }else{pending={id,type,el:anchor};anchor.classList.add('selected-terminal');$('wire-status').classList.add('wiring');$('wire-status').textContent=terminalName(id,lab.mapping)+' → choose the other end';selectedWire=null;drawWires();}}
function removeCable(id=selectedWire){if(!id){toast('Click a cable to select it first');return;}lab.patchbay.remove(id);selectedWire=null;lab.sync();updatePower();drawWires();refresh();if(notebookTab==='connections')renderNotebook();}
function updatePower(){lab.sync();if(lab.powered&&!lastPower){lab.powerOnReset();monitor.reset();}if(!lab.powered&&lastPower){monitor.running=false;entryQueue=[];}lastPower=lab.powered;}
function preset(kind='dac'){entryQueue=[];monitor.reset();lab.setup(kind);lastPower=false;updatePower();scope.lastTriggered=null;scope.frozen=null;lab.scope.clear();lab.nextSample=lab.time;$('desk-welcome').classList.add('hidden');clearPending();drawWires();refresh();toast('Connected '+(kind==='dac'?'the photo DAC setup':kind+' setup')+'. Type on the board to begin.');}
function typeKey(key){entryQueue=[];return guard(()=>{monitor.key(key);refreshLCD();if(notebookTab==='terminal')renderTerminal();});}
function focusLCD(){if(!lab.powered||!lab.keyboardConnected){toast(!lab.powered?'Connect AC power and switch the trainer ON':'Connect the keyboard to the CN7 PS/2 socket');return;}$('lcd-input').focus({preventScroll:true});$('keyboard-focus').classList.add('active');}
function queueLines(lines,start=0x2000){paused=false;$('simulation-pause').textContent='Ⅱ Simulation';if(!lab.powered||!lab.keyboardConnected)throw new Error('Power the trainer and connect the keyboard first');entryQueue=[];monitor.reset();for(const key of ['1','A',...hex(start,4),'Enter'])monitor.key(key);for(const line of lines){for(const char of line)entryQueue.push(char);entryQueue.push('Enter');}entryDue=performance.now();focusLCD();toast('Entering '+lines.length+' instructions, one LCD line at a time');}
function turnKnob(name,steps=1,fine=false){if(name.startsWith('dac-')){const result=turnDACTrim(lab,name,steps,fine);toast('DAC '+(result.channel?'Y':'X')+' '+result.parameter+' '+result.value.toFixed(3));}
  else if(name==='adc-level'){const result=turnADCLevel(lab,steps,fine);toast('ADC IN'+result.channel+' '+result.value.toFixed(3)+' V · local VIN');}
  else if(name==='source-frequency'){lab.generator.frequency=clamp(lab.generator.frequency*Math.pow(1.1,steps*(fine?.1:1)),.01,100000);lab.sync();}
  else if(lab.scopePower())scope.knob(name,steps,fine);else toast('Connect oscilloscope AC power');const knob=document.querySelector(`[data-knob="${name}"]`);if(knob){const current=Number(knob.dataset.turn||-25)+steps*12;knob.dataset.turn=current;knob.style.setProperty('--turn',current+'deg');}refresh();}
function refreshLCD(){const lines=monitor.lines;drawLCD($('trainer-lcd'),lines,lab.powered,Math.floor(performance.now()/500)%2===0);const content=lines.map(s=>s.trimEnd()).join('\n');if($('lcd-accessible').textContent!==content)$('lcd-accessible').textContent=content;}
function refresh(){refreshLCD();$('equipment-scope').classList.toggle('instrument-on',lab.scopePower());$('trainer-power').classList.toggle('on',lab.boardSwitch);$('trainer-power-led').classList.toggle('on',lab.powered);$('trainer-red-led').classList.toggle('on',monitor.running);$('mains-switch').classList.toggle('off',!lab.stripOn);$('dac-power-led').classList.toggle('on',lab.modulePower.dac);$('adc-eoc-led').classList.toggle('on',lab.modulePower.adc&&!!lab.adc.eoc);$('scope-usb').classList.toggle('inserted',scope.usbInserted);for(let n=0;n<4;n++)$('coil-'+n).classList.toggle('on',!!(lab.motor.phase&1<<n));$('motor-rotor').style.transform=`rotate(${lab.motor.angle%360}deg)`;$('motor-rotor').setAttribute('aria-label',`Motor shaft ${lab.motor.angle.toFixed(1)} degrees; coils ${hex(lab.motor.phase)}`);
  $('study-clock').setAttribute('aria-pressed',String(lab.studySingleStep));$('study-clock').classList.toggle('step-on',lab.studySingleStep);for(let b=0;b<8;b++)$('study-data-'+b).classList.toggle('on',lab.modulePower.led&&lab.studyBusConnected&&!!(lab.studyBus.data&1<<b));for(const [name,on]of Object.entries({cs:lab.studyBus.cs,a0:lab.studyBus.address&1,a1:lab.studyBus.address&2,rd:lab.studyBus.read,wr:lab.studyBus.write}))$('study-signal-'+name).classList.toggle('on',lab.modulePower.led&&lab.studyBusConnected&&!!on);for(let p=0;p<3;p++){for(let b=0;b<8;b++)$('id-lamp-'+p+'-'+b).classList.toggle('on',!!(lab.ledBytes[p]&1<<b));$('id-value-'+p).textContent=lab.modulePower.led?hex(lab.ledBytes[p]):'--';}
  $('desk-power-state').classList.toggle('on',lab.powered);$('desk-power-state').innerHTML='<i></i> Trainer '+(lab.powered?'ON':'OFF');$('desk-simulation-time').textContent='SIM '+lab.time.toFixed(3)+' s';$('desk-status').textContent=lab.conflictText||(!lab.powered?'Connect AC power and switch the trainer ON.':!lab.keyboardConnected?'Connect the PS/2 keyboard to CN7.':paused?'PAUSED · PC '+hex(lab.cpu.pc,4):monitor.running?'Executing · PC '+hex(lab.cpu.pc,4)+'H · '+lab.cpu.instructions.toLocaleString()+' instructions':monitor.error||'LCD '+monitor.state+' · PC '+hex(lab.cpu.pc,4)+'H · RAM 2000H–FFFFH');$('source-display').textContent=Number(lab.generator.frequency.toPrecision(3))+' Hz '+lab.generator.type.toUpperCase();$('keyboard-focus').classList.toggle('active',document.activeElement===$('lcd-input'));document.querySelector('[data-scope-button="run"]').classList.toggle('lit',scope.run);
  const frame=screen.draw();if(!pending&&!selectedWire){const hint=circuitHint(lab);$('wire-status').textContent=hint||'Click a labelled connector, then its destination. Esc cancels.';$('wire-status').classList.toggle('hint',!!hint);}const live=$('circuit-readings');if(live)live.textContent='DAC X · OUT '+hex(lab.mapping[0].base)+' · '+hex(lab.dacs[0].code)+' · '+lab.dacVoltages[0].toFixed(3)+' V\nDAC Y · OUT '+hex(lab.mapping[0].base+1)+' · '+hex(lab.dacs[1].code)+' · '+lab.dacVoltages[1].toFixed(3)+' V';const desc=lab.scopePower()?'Menu '+scope.menu+'; '+scope.softkeys().map((k,n)=>k.label+' '+k.value+(scope.menu==='measure'&&frame?' '+measurement(frame.points,'c'+scope.measurements[n].source,scope.measurements[n].type):'')).join('; ')+'; '+(scope.run?'Running':'Stopped')+'; '+(frame?.points.some(p=>p.c0!==null||p.c1!==null)?'Signal acquired':'No connected signal')+'; '+scope.message:'Oscilloscope power OFF';if($('scope-accessible').textContent!==desc)$('scope-accessible').textContent=desc;
  if(scope.requestScreenshot){scope.requestScreenshot=false;const image=$('tek-screen').toDataURL('image/png');$('tek-screen').toBlob(blob=>{if(!blob)return;const name='TEK'+String(scope.usbFiles.length+1).padStart(3,'0')+'.png';scope.usbFiles.push({name,type:'image',data:image});download(blob,name);});}if(scope.requestExport){const file=scope.requestExport;scope.requestExport=null;if(file.type==='image'){const a=document.createElement('a');a.href=file.data;a.download=file.name;a.click();}else download(file.type==='waveform'?csv(file.data):JSON.stringify(file.data,null,2),file.name);}
}
function download(data,name){const blob=data instanceof Blob?data:new Blob([data],{type:name.endsWith('.csv')?'text/csv':'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),20000);}
function csv(rows){if(!rows?.length)return '';const keys=Object.keys(rows[0]);return keys.join(',')+'\n'+rows.map(row=>keys.map(k=>String(row[k]??'').replaceAll(',',';')).join(',')).join('\n');}
function openNotebook(tab=notebookTab){notebookTab=tab;$('notebook').classList.add('open');renderNotebook();}
function renderTerminal(){if(notebookTab!=='terminal'||!$('notebook').classList.contains('open')||monitor.historySerial===lastHistory)return;lastHistory=monitor.historySerial;const el=$('terminal-history');if(!el)return;const panel=$('notebook-content'),nearBottom=panel.scrollHeight-panel.scrollTop-panel.clientHeight<60;el.innerHTML=monitor.history.map(row=>`<div class="terminal-entry"><span class="terminal-address">${row.address===null?'·':hex(row.address,4)}</span><b>${esc(row.input)}</b><div class="terminal-output">${esc(row.output)}</div></div>`).join('')||'<p class="terminal-empty">Each entered LCD command and instruction appears here.</p>';if(nearBottom)$('notebook-content').scrollTop=$('notebook-content').scrollHeight;}
function renderNotebook(){document.querySelectorAll('[data-notebook]').forEach(b=>b.classList.toggle('active',b.dataset.notebook===notebookTab));const el=$('notebook-content');
  if(notebookTab==='procedures')el.innerHTML=`<span class="manual-eyebrow">FROM YOUR LAB SHEETS & VIDEO</span><h3>The Kitek LCD monitor</h3><p>The trainer accepts one command or one instruction at a time. The physical keyboard and your own keyboard both feed the 20 × 2 LCD.</p><ol><li>Connect the keyboard to <b>CN7</b> and AC power. Switch the board ON. The LCD shows <code>8085 LCD TRAINER / M85-0X</code>.</li><li>Press <kbd>1</kbd> → <kbd>A</kbd>. At <code>RAM ADR:</code>, type <kbd>2000</kbd> and Enter.</li><li>Type <code>MVI A 09</code> and Enter. Only a correctly spaced line is assembled and stored. The next address, <b>2002</b>, appears. Continue with <code>MVI B 04</code>, <code>ADD B</code>, <code>RST 5</code>.</li><li>Press the red <b>Reset key</b>. Press <kbd>G</kbd>, type <kbd>2000</kbd>, then <kbd>.</kbd> to execute.</li><li>Press <kbd>R</kbd>, then <kbd>A</kbd>. A reads <code>0D</code>. Reset returns to the monitor and preserves RAM and result registers.</li></ol><button class="manual-primary" data-action="focus-lcd">Type on board →</button><button class="manual-secondary" data-action="addition">Open sheet example</button><h4>Other monitor commands</h4><table><tr><td>1 → C</td><td>Start address, end address, Enter; then Enter for each disassembled instruction.</td></tr><tr><td>M address Enter</td><td>Examine or write one memory byte per Enter.</td></tr><tr><td>T address Enter</td><td>Enter steps one CPU instruction.</td></tr><tr><td>I / O</td><td>Read a hex port / write PORT DATA.</td></tr><tr><td>F / B</td><td>Fill START END BYTE / copy START END DEST.</td></tr><tr><td>R → register</td><td>Inspect or edit A B C D E H L F SP PC BC DE HL.</td></tr><tr><td>. / Esc</td><td>Return to menu / Reset.</td></tr></table><p>All bare numbers on the monitor are hexadecimal. Use exactly one ASCII space: MVI A 80 or LXI D 0000. Only MOV uses a comma: MOV A,B. H suffixes, extra/leading/trailing spaces and comments are invalid. Backspace/Delete and coding-address arrows do nothing; Reset and re-enter the address to correct a mistake. User RAM is available from <b>2000H through FFFFH</b>.</p><details><summary>Instruction set & debugging</summary><p>${INSTRUCTIONS.length} documented opcode encodings, including arithmetic, flags, stack, calls, I/O, RIM/SIM, and interrupt controls. The preserved <a href="advanced.html" target="_blank">advanced workspace</a> provides the source editor, full register and memory inspectors, bus trace, interrupt controls, and Intel HEX tools.</p></details><p class="manual-note">This monitor follows the prompts and procedure visible in your references. The proprietary Kitek monitor ROM was not supplied, so unobserved firmware wording is reconstructed.</p>`;
  else if(notebookTab==='experiments'){const program=experimentProgram(experiment,lab);el.innerHTML=`<span class="manual-eyebrow">ENTER THROUGH THE TRAINER LCD</span><h3>Lab programs</h3><select id="experiment-select" class="experiment-select" aria-label="Experiment">${EXPERIMENTS.map(([value,title])=>`<option value="${value}" ${experiment===value?'selected':''}>${title}</option>`).join('')}</select><label>Six-digit ID <input id="student-id" class="id-field" aria-label="Six-digit student ID" maxlength="6" value="${lab.id}" inputmode="numeric"></label><p class="manual-note">PA = ${lab.id.slice(0,2)}, PB = ${lab.id.slice(2,4)}, PC = ${lab.id.slice(4,6)} on the independent SC-01 8255. Values are packed BCD, with two groups of four LEDs per port.</p><p>${esc(program.notes)}</p><div class="experiment-toolbar"><button class="manual-secondary" data-action="wire-experiment">Connect this circuit</button><button class="manual-primary" data-action="type-experiment">Type each line on LCD</button><button class="manual-secondary" data-action="run-program">G 2000 . → Run</button></div><p id="entry-progress" class="scope-measurement-note">${entryQueue.length?'Entering on LCD…':'No instruction is stored until its Enter is processed.'}</p><pre>${program.instructions.map(r=>hex(r.address,4)+'  '+r.text).join('\n')}</pre><button class="manual-secondary" data-action="export-program">Save assembly</button><button class="manual-secondary" data-action="export-hex">Save RAM as Intel HEX</button><p class="manual-note">“Type each line” sends the same keystrokes and Enter events as the keyboard. It shows every line on the LCD in sequence; it does not batch-load CPU memory.</p>`;}
  else if(notebookTab==='terminal'){el.innerHTML='<span class="manual-eyebrow">ONE ENTER · ONE PROCESSED LINE</span><h3>Monitor terminal history</h3><div class="experiment-toolbar"><button class="manual-secondary" data-action="focus-lcd">Focus LCD</button><button class="manual-secondary" data-action="stop-entry">Stop typing</button><button class="manual-secondary" data-action="export-history">Save history</button></div><div id="terminal-history"></div>';lastHistory=-1;renderTerminal();}
  else if(notebookTab==='connections')renderConnections(el);
  else if(notebookTab==='reference')renderReferences(el);
}
function renderConnections(el){el.innerHTML=`<span class="manual-eyebrow">PATCH LEADS & SIGNAL PATHS</span><h3>Connections</h3><div class="circuit-readings" id="circuit-readings"></div><p>Use Auto connector for a complete ribbon, supply, keyboard or AC cord. Select Jumper to wire individual header pins. A scope trace needs a signal tip and a ground clip.</p><button class="manual-secondary" data-action="preset-dac">Photo DAC circuit</button><button class="manual-secondary" data-action="clear-cables">Unplug all cables</button><div>${lab.patchbay.cables.map(c=>`<div class="connection-row"><i style="background:${esc(c.color)}"></i><div>${esc(terminalName(c.a,lab.mapping,c.type))} ↔ ${esc(terminalName(c.b,lab.mapping,c.type))}<small>${esc(c.type)} ${c.pairs?'· '+c.pairs.length+' signals':''}</small></div><button data-remove-cable="${c.id}" aria-label="Remove ${esc(c.a)} to ${esc(c.b)}">×</button></div>`).join('')||'<p>No cables connected.</p>'}</div><p class="manual-note">${esc(lab.conflictText||'No conflicting drivers detected.')}</p><details><summary>Individual signal pins / patch panel</summary><p>Select two terminals below to connect a jumper. These are the same electrical nodes as the visible hardware.</p><select id="pin-module" aria-label="Pin connector">${['trainer.ppi0','trainer.ppi1','trainer.bus','led.bus','dac','adc','led','motor','logic','timer'].map(s=>`<option>${s}</option>`).join('')}</select><div id="pin-panel" class="pin-grid"></div></details><details><summary>Address map & CPU</summary><p class="manual-note">Supplied IC-02 sheet: analog ports 00–03. SC-01 ID card and stepper sheets: ports 30–33 in alternate lab profiles. The connected SC-01 CPU bus selects its independent PPI at this range; unplug it for the trainer’s motor PPI. Analog stays at 00–03. Timer C4–C7 is a configurable simulator default.</p><div class="config-box"><label>8255-1 base <input id="ppi0-base" value="${hex(lab.mapping[0].base)}" maxlength="2" size="3"></label><label>SC-01 / motor base <input id="ppi1-base" value="${hex(lab.mapping[1].base)}" maxlength="2" size="3"></label><label>8253 base <input id="pit-base" value="${hex(lab.timerBase)}" maxlength="2" size="3"></label><label>CPU Hz <input id="cpu-clock" type="number" min="1" max="100000000" value="${lab.clock}"></label><button class="manual-secondary" data-action="apply-addresses">Apply addresses</button></div><p>Full RAM: 2000H–FFFFH. Reserved monitor region: 0000H–1FFFH. The 6.144 MHz crystal is modeled as a 3.072 MHz CPU clock.</p><label>Breakpoint hex <input id="breakpoint-address" value="2000" size="5" maxlength="4"></label><button class="manual-secondary" data-action="toggle-breakpoint">Toggle breakpoint</button><p>Breakpoints: ${[...lab.breakpoints].map(v=>hex(v,4)).join(', ')||'none'}</p></details><details><summary>ADC inputs / analog source / DAC calibration</summary><label>Channel <select id="adc-channel">${Array.from({length:8},(_,i)=>`<option value="${i}" ${lab.adcChannel===i?'selected':''}>IN${i}</option>`).join('')}</select></label><label>Source <select id="adc-source">${['jack','knob','generator'].map(v=>`<option ${lab.adcInputSources[lab.adcChannel]===v?'selected':''}>${v}</option>`).join('')}</select></label><label>VIN <input id="adc-voltage" type="number" min="0" max="5" step=".01" value="${lab.adcInputs[lab.adcChannel]}"></label><label>ADC clock Hz <input id="adc-clock" type="number" value="${lab.adc.clock}" min="10000" max="1280000"></label><label>Vref <input id="adc-vref" type="number" min=".1" max="20" step=".1" value="${lab.adc.vref}"></label><label>Source amplitude V <input id="source-amplitude" type="number" min="0" max="20" step=".1" value="${lab.generator.amplitude}"></label><label>Offset V <input id="source-offset" type="number" min="-20" max="20" step=".1" value="${lab.generator.offset}"></label><label>DC V <input id="source-dc" type="number" min="-20" max="20" step=".1" value="${lab.generator.dc}"></label><label>Duty % <input id="source-duty" type="number" min="1" max="99" value="${lab.generator.duty}"></label><p>ADC code ${hex(lab.adc.code)} · ${lab.adc.conversions} conversions. DAC X ${lab.dacVoltages[0].toFixed(3)} V, Y ${lab.dacVoltages[1].toFixed(3)} V. Turn the four board trimmers to calibrate gain and offset.</p></details><details><summary>Oscilloscope probes / trigger / math / USB</summary>${[0,1].map(i=>`<label>CH${i+1} physical probe <select data-probe="${i}">${[1,10,100,1000].map(v=>`<option value="${v}" ${lab.probes[i].physical===v?'selected':''}>${v}×</option>`).join('')}</select></label>`).join('')}<p>The scope menu Probe setting compensates the physical probe attenuation. Mismatched values change displayed voltage, as on the instrument.</p><label>USB drive <input id="usb-inserted" type="checkbox" ${scope.usbInserted?'checked':''}></label><label>Pulse width s <input id="trigger-width" type="number" min=".000000001" max="50" step=".0001" value="${scope.trigger.width}"></label><label>Video standard <select id="video-standard"><option ${scope.trigger.standard==='NTSC'?'selected':''}>NTSC</option><option ${scope.trigger.standard==='PAL'?'selected':''}>PAL</option></select></label><label>Video line <input id="video-line" type="number" min="1" max="625" value="${scope.trigger.line}"></label><label>Holdoff s <input id="trigger-holdoff" type="number" min="0" max="50" step=".001" value="${scope.trigger.holdoff}"></label><label>Math V/div <input id="math-scale" type="number" min=".001" max="1000" step=".1" value="${scope.math.scale}"></label><button class="manual-secondary" data-action="export-capture">Export scope CSV</button><button class="manual-secondary" data-action="export-log">Export data log</button><p class="manual-note">The front-panel controls operate the simulated acquisition. The virtual sample rate is ${lab.scopeRate.toLocaleString()} samples/s; the 50 MHz / 500 MS/s label identifies the photographed instrument, not the numerical simulation bandwidth.</p><label>Capture samples/s <input id="scope-rate" type="number" min="1000" max="1000000" step="1000" value="${lab.scopeRate}"></label></details><details><summary>8253 clock inputs & motor</summary>${lab.timer.channels.map((c,n)=>`<label>CLK${n} Hz <input data-timer-clock="${n}" type="number" min="0" max="10000000" value="${c.clock}"></label>`).join('')}<p>Patch CN2 timer OUT pins to other terminals. External clock and gate jumpers override the counter's internal clock and gate. Motor ${lab.motor.steps.toFixed(1)} steps, ${lab.motor.angle.toFixed(1)}°, ${lab.motor.invalid} invalid phase transitions.</p></details><details><summary>Digital switches / interrupts / LED polarity</summary><p>Logic switch terminals drive 0 or +5 V. Wire them to a PPI input, SID or an interrupt pin.</p><div class="pin-grid">${lab.switches.map((v,n)=>`<button data-logic="${n}" class="${v?'selected':''}">D${n}: ${v}</button>`).join('')}</div><label>LED active low <input id="led-active-low" type="checkbox" ${lab.activeLowLED?'checked':''}></label><label>Interrupt vector <select id="interrupt-vector">${[0x24,0x2c,0x34,0x3c,0x38].map(v=>`<option value="${v}">${hex(v,4)}H</option>`).join('')}</select></label><label>RAM handler <input id="interrupt-handler" value="2100" size="5" maxlength="4"></label><button class="manual-secondary" data-action="set-vector">Set vector</button></details>`;renderPinPanel();}
function renderPinPanel(){const select=$('pin-module'),el=$('pin-panel');if(!select||!el)return;const mod=select.value,signals=mod.endsWith('.bus')?BUS_SIGNALS.map(s=>busTerminal(mod,s)):mod==='logic'?Array.from({length:8},(_,n)=>'logic.'+n):mod==='timer'?Array.from({length:3},(_,n)=>['clock','gate','out'].map(s=>`trainer.pit${n}.${s}`)).flat():PORT_SIGNALS.map(s=>mod+'.'+s);el.innerHTML=signals.map(id=>`<button data-panel-terminal="${id}" class="${pending?.id===id?'selected':''}" title="${id}">${id.split('.').slice(mod==='timer'?1:-1).join('.')}</button>`).join('');}
function renderReferences(el){const photoNames=['12.59.46 (1)','12.59.46','13.00.33 (1)','13.00.33','13.00.34 (1)','13.00.34 (2)','13.00.34','13.00.35 (1)','13.00.35 (2)','13.00.35 (3)','13.00.35','13.00.36'];el.innerHTML=`<span class="manual-eyebrow">YOUR PHOTOS, VIDEOS & PRIMARY SOURCES</span><h3>The lab references</h3><p>All 22 photos and both videos are copied inside this project, including nine board close-ups and the final scope waveform reference. The video review includes a frame for each second of both timelines.</p><div class="reference-grid">${photoNames.map((n,i)=>{const path='references/lab/photos/'+encodeURIComponent('WhatsApp Image 2026-10-31 at '+n+'.jpeg');return `<a href="${path}" target="_blank"><img src="${path}" loading="lazy" alt="Lab reference ${i+1}">Reference ${i+1} · ${n}</a>`;}).join('')}</div><h4>Detailed board and stepper photos</h4><div class="reference-grid">${[['03c9bd24-43f8-4dbc-80da-f4a2ce7ee3ce','Complete trainer and motor'],['9447c5ac-8cd6-449b-a830-9e6d400524ac','PCB close-up (partly obscured)'],['a39fa63d-d0be-4dc0-82ac-ff1004051b1b','CN5 supply, DB9 and brass gear'],['6b10e214-c4fa-4ffa-a9e3-ad46c568c932','CN4 ribbon and 8255-1'],['3f627495-cb84-418e-a960-d9450d4e163a','IC-08 transistor and supply detail'],['658e3e5c-409f-4a7a-9969-58c4bc2ba8f0','CN1 and CN2 wiring detail']].map(([id,label])=>`<a href="references/lab/details/codex-clipboard-${id}.jpg" target="_blank"><img src="references/lab/details/codex-clipboard-${id}.jpg" loading="lazy" alt="${label}">${label}</a>`).join('')}</div><h4>SC-01 8255 study card</h4><div class="reference-grid">${['7e1b32cc-2772-456e-becf-e4adf6b646b8','422de2a5-2ac6-4ade-9aec-fc8cc92aa141','ec5bc856-f5f8-4889-8574-7ca1ee23f1cc'].map((id,i)=>`<a href="references/lab/details/codex-clipboard-${id}.jpg" target="_blank"><img src="references/lab/details/codex-clipboard-${id}.jpg" loading="lazy" alt="SC-01 8255 study card view ${i+1}">SC-01 · view ${i+1}</a>`).join('')}</div><p>The SC-01 has its own 8255, edge-mounted PA/PB/PC LEDs, AD0–AD7 and /CS/A0/A1//RD//WR indicators, a 50-pin CPU bus, a 26-pin port header, and a single-step switch/key. The model shows the latest instruction-level bus transaction; it does not claim physical machine-cycle single-stepping.</p><h4>Final scope waveform reference</h4><a href="references/lab/details/oscilloscope-waveforms-reference.jpeg" target="_blank"><img class="reference-video" loading="lazy" src="references/lab/details/oscilloscope-waveforms-reference.jpeg" alt="Supplied Tektronix yellow ramp, square and triangle display reference"></a><h4>Supplied lab PDFs</h4><p><a href="references/lab/manuals/01_id_output_8255.pdf" target="_blank">ID output · 30–33 · 425050</a><br><a href="references/lab/manuals/02_clockwise_stepper_motor.pdf" target="_blank">Clockwise stepper · F9 F5 F6 FA · 03A6 delay</a><br><a href="references/lab/manuals/IC-02_DAC_8085_%26_8086_Waveform_Generation%5B1%5D.pdf" target="_blank">IC-02 DAC waveform programs · 8085 page 1</a></p><p class="manual-note">The PDFs use conventional printed Intel commas/H notation. The LCD follows your lab-entry rules: MVI A 80, MOV A,B, single spaces, no H suffixes, no Backspace/Delete. Only syntax is checked; a logically wrong but valid instruction is still accepted.</p><h4>Videos</h4>${['13.02.59 (1)','13.03.47'].map((n,i)=>`<video class="reference-video" controls preload="metadata" src="references/lab/videos/${encodeURIComponent('WhatsApp Video 2026-10-31 at '+n+'.mp4')}"></video><small>Video ${i+1} · ${i?134:281} seconds</small>`).join('')}<h4>Manufacturer documents</h4><p><a href="https://kitektechnologies.com/8085-8086-process-trainer.html" target="_blank" rel="noreferrer">Kitek M85-04 product details</a> · <a href="references/lab/M85-04-manufacturer.pdf" target="_blank">Local manufacturer specification PDF</a></p><p><a href="https://download.tek.com/manual/071272203Web_RevA.pdf" target="_blank" rel="noreferrer">Tektronix TDS1000C/TDS2000C user manual</a></p><h4>What is reproduced</h4><p>PCB layout, grey module cases, 20 × 2 green LCD, PS/2 keyboard workflow, separate 8255 ID LEDs, dual DAC outputs, ADC conversion timing, stepper phase sequence, probe wiring and the photographed scope's front controls.</p><p class="manual-note">This is an instructional digital reconstruction. The supplied sheets establish 00–03 for the analog PPI and 30–33 for ID/stepper. The exact IC-01 schematic, original monitor ROM and analog calibration data were not supplied. The 03A6 delay service is a compatibility implementation. Configurable pin conventions and ideal electrical models are documented in the project guide. Tektronix video triggering uses ideal sync pulses; proprietary firmware and real hardware noise/bandwidth are not emulated.</p><p><a href="docs/USER-GUIDE.md" target="_blank">Local user guide and model details</a></p>`;}
function saveProject(){download(JSON.stringify(snapshotDesk(lab,monitor,scope,layout,view)),'8085-lab.85desk');toast('Saved complete desk, memory, wiring and instrument settings');}
async function loadFile(file){if(!file)return;const text=await file.text();if(file.name.endsWith('.85desk')||file.name.endsWith('.json')){const restored=restoreDesk(JSON.parse(text));lab=restored.lab;monitor=restored.monitor;scope=restored.scope;screen.tds=scope;lab.traceEnabled=false;layout={...structuredClone(INITIAL_LAYOUT),...restored.layout};if(restored.view)view=restored.view;for(const [id,r]of Object.entries(layout)){const el=$('equipment-'+id);if(el){el.style.left=r.x+'px';el.style.top=r.y+'px';}}entryQueue=[];lastPower=lab.powered;$('desk-welcome').classList.add('hidden');updateView();drawWires();refresh();toast('Desk restored. Press G to execute the stored program.');}
  else if(file.name.endsWith('.hex')){const data=importHex(text);for(let a=0x2000;a<=65535;a++)if(data.written[a]){lab.memory[a]=data.memory[a];lab.written[a]=1;}monitor.reset();monitor.record('IMPORT '+file.name,'Intel HEX data loaded into user RAM');toast('Intel HEX imported');}
  else{const rows=parseTrainerProgram(text);if(!rows.length)throw new Error('No instructions in this file');queueLines(rows.map(row=>row.text));}
  if($('notebook').classList.contains('open'))renderNotebook();}
function doAction(action){const idInput=$('student-id');if(idInput&&/^\d{6}$/.test(idInput.value))lab.id=idInput.value;if(action==='focus-lcd'){focus('trainer');$('notebook').classList.remove('open');focusLCD();}else if(action==='addition'){experiment='addition';openNotebook('experiments');}else if(action==='preset-dac')preset('dac');else if(action==='clear-cables'){lab.patchbay.clear();lab.sync();updatePower();clearPending();drawWires();renderNotebook();refresh();}else if(action==='wire-experiment')preset(experimentProgram(experiment,lab).wiring);else if(action==='type-experiment'){queueLines(experimentProgram(experiment,lab).lines);focus('trainer');$('notebook').classList.remove('open');}else if(action==='run-program'){entryQueue=[];monitor.reset();for(const key of ['G',...'2000','.'])monitor.key(key);refresh();}else if(action==='stop-entry'){entryQueue=[];toast('LCD typing stopped');}else if(action==='export-program')download(experimentProgram(experiment,lab).source,experiment+'.asm');else if(action==='export-hex')download(exportHex(lab.memory,lab.written),'8085-memory.hex');else if(action==='export-history')download(monitor.history.map(r=>(r.address===null?'':hex(r.address,4)+' ')+r.input+'\n  '+r.output).join('\n'),'monitor-history.txt');else if(action==='export-capture')download(csv(scope.frame().points),'scope-capture.csv');else if(action==='export-log')download(csv(scope.log),'scope-log.csv');else if(action==='apply-addresses'){const bases=[$('ppi0-base'),$('ppi1-base'),$('pit-base')].map(e=>parseInt(e.value,16));if(!bases.every(v=>Number.isInteger(v)&&v>=0&&v<=252))throw new Error('Enter valid hexadecimal base addresses, 00 to FC');for(let i=0;i<3;i++)for(let j=i+1;j<3;j++)if(Math.abs(bases[i]-bases[j])<4)throw new Error('Peripheral addresses overlap');lab.configureMapping(0,'io',bases[0]);lab.configureMapping(1,'io',bases[1]);lab.timerBase=bases[2];lab.clock=clamp(Number($('cpu-clock').value)||3072000,1,1e8);toast('Address map updated');renderNotebook();}else if(action==='toggle-breakpoint'){const a=monitor.addr($('breakpoint-address').value.toUpperCase());lab.breakpoints.has(a)?lab.breakpoints.delete(a):lab.breakpoints.add(a);renderNotebook();}else if(action==='set-vector'){lab.setVector(Number($('interrupt-vector').value),monitor.addr($('interrupt-handler').value.toUpperCase(),0x2000));toast('Interrupt vector installed in monitor region');}}

document.addEventListener('click',event=>guard(()=>{const t=event.target,button=t.closest('button,[role="button"]');if(t.closest('[data-focus]')){focus(t.closest('[data-focus]').dataset.focus);return;}if(t.closest('[data-action]')){doAction(t.closest('[data-action]').dataset.action);return;}if(t.closest('[data-notebook]')){openNotebook(t.closest('[data-notebook]').dataset.notebook);return;}if(t.closest('[data-open-notebook]')){openNotebook(t.closest('[data-open-notebook]').dataset.openNotebook);return;}
  if(t.closest('[data-remove-cable]')){removeCable(t.closest('[data-remove-cable]').dataset.removeCable);return;}if(t.closest('[data-panel-terminal]')){const id=t.closest('[data-panel-terminal]').dataset.panelTerminal;if(pending){const from=pending.id;clearPending();lab.cable(from,id,'jumper',$('wire-color').value);drawWires();refresh();}else{pending={id,type:'jumper',el:button};$('wire-status').textContent=id+' → choose another pin';}renderPinPanel();return;}
  if(t.closest('[data-wire-target]')){const label=t.closest('[data-wire-target]'),attr=label.dataset.wireKind==='connector'?'data-connector':'data-terminal',target=document.querySelector(`[${attr}="${label.dataset.wireTarget}"]`);if(target)selectTerminal(target);return;}if(t.closest('[data-terminal],[data-connector]')){selectTerminal(t);return;}if(t.closest('[data-cable]')){selectedWire=t.closest('[data-cable]').dataset.cable;clearPending();$('wire-status').textContent='Cable selected: '+terminalName(lab.patchbay.cables.find(c=>c.id===selectedWire)?.a,lab.mapping)+' ↔ '+terminalName(lab.patchbay.cables.find(c=>c.id===selectedWire)?.b,lab.mapping)+' · Delete to unplug';drawWires();return;}if(t.closest('[data-scope-button]')){if(!lab.scopePower())throw new Error('Connect scope AC power and turn it ON');scope.press(t.closest('[data-scope-button]').dataset.scopeButton);refresh();return;}if(t.closest('[data-softkey]')){if(lab.scopePower()){scope.soft(Number(t.closest('[data-softkey]').dataset.softkey));refresh();}return;}
  if(t.closest('[data-logic]')){const n=Number(t.closest('[data-logic]').dataset.logic);lab.switches[n]=1-lab.switches[n];lab.sync();renderNotebook();return;}if(t.closest('[data-key]')){let key=t.closest('[data-key]').dataset.key;if(key==='Shift'){shift=!shift;button.classList.toggle('pressed',shift);return;}if(key==='Caps'){caps=!caps;button.classList.toggle('pressed',caps);return;}if(key==='Esc')key='Escape';if(key==='Space')key=' ';if(key==='Tab'){typeKey('Tab');focusLCD();return;}if(key==='4'&&shift)key='$';if(key==='$'&&monitor.state==='goAddress')key='.';if(key.length===1||['Enter','Backspace','Delete','Escape','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(key))typeKey(key);shift=false;focusLCD();return;}
  const id=button?.id;if(id==='toggle-labels'){view.labels=view.labels===false;updateView();}else if(id==='reference-setup'){preset('dac');focus('all');}else if(id==='empty-bench'){$('desk-welcome').classList.add('hidden');toast('Click two connector housings or pins to attach a cable');}else if(id==='trainer-power'){lab.boardSwitch=!lab.boardSwitch;updatePower();refresh();}else if(id==='mains-switch'){lab.stripOn=!lab.stripOn;updatePower();refresh();}else if(id==='scope-power'){lab.scopeSwitch=!lab.scopeSwitch;lab.sync();refresh();}else if(id==='trainer-reset'){entryQueue=[];monitor.reset();refresh();}else if(id==='study-clock'){lab.studySingleStep=!lab.studySingleStep;toast(lab.studySingleStep?'SC-01: start with G, then press STEP for each instruction':'SC-01: continuous CPU clock');refresh();}else if(id==='study-step'){monitor.hardwareStep();refresh();}else if(id==='trainer-vector'){lab.cpu.setLine('TRAP',1);setTimeout(()=>lab.cpu.setLine('TRAP',0),100);monitor.record('VECTOR KEY','TRAP asserted');toast('TRAP interrupt asserted');}else if(id==='keyboard-focus'){focus('lcd');focusLCD();}else if(id==='open-notebook')openNotebook();else if(id==='close-notebook')$('notebook').classList.remove('open');else if(id==='remove-wire')removeCable();else if(id==='zoom-in')zoom(1.2);else if(id==='zoom-out')zoom(1/1.2);else if(id==='save-bench')saveProject();else if(id==='load-bench')$('bench-file').click();else if(id==='desk-help')$('lab-help').showModal();else if(id==='close-help'||id==='start-lab')$('lab-help').close();else if(id==='simulation-pause'){paused=!paused;button.textContent=paused?'▶ Simulation':'Ⅱ Simulation';}else if(id==='scope-usb'){scope.usbInserted=!scope.usbInserted;toast('Virtual USB '+(scope.usbInserted?'inserted':'removed'));refresh();}else if(id==='source-shape'){const values=['sine','square','triangle','saw','dc','noise'];lab.generator.type=values[(values.indexOf(lab.generator.type)+1)%values.length];lab.sync();refresh();}
}));
document.addEventListener('change',event=>guard(()=>{const el=event.target,id=el.id,n=Number(el.value);if(id==='experiment-select'){experiment=el.value;renderNotebook();}else if(id==='student-id'){if(!/^\d{6}$/.test(el.value))throw new Error('Enter exactly six digits, including any leading zeroes');lab.id=el.value;renderNotebook();}else if(id==='simulation-speed')speed=n;else if(id==='pin-module')renderPinPanel();else if(id==='cable-type')clearPending();else if(id==='bench-file'){loadFile(el.files[0]).catch(e=>toast(e.message));el.value='';}else if(id==='adc-channel'){lab.adcChannel=n;renderNotebook();}else if(id==='adc-source')lab.adcInputSources[lab.adcChannel]=el.value;else if(id==='adc-voltage')lab.adcInputs[lab.adcChannel]=clamp(n,0,lab.adc.vref);else if(id==='adc-clock')lab.adc.clock=clamp(n,10000,1280000);else if(id==='adc-vref')lab.adc.vref=clamp(n,.1,20);else if(id==='source-amplitude')lab.generator.amplitude=clamp(n,0,20);else if(id==='source-offset')lab.generator.offset=clamp(n,-20,20);else if(id==='source-dc')lab.generator.dc=clamp(n,-20,20);else if(id==='source-duty')lab.generator.duty=clamp(n,1,99);else if(id==='scope-rate'){lab.scopeRate=clamp(n,1000,1000000);lab.scope.clear();lab.nextSample=lab.time;}else if(el.dataset.probe!==undefined)lab.probes[Number(el.dataset.probe)].physical=n;else if(el.dataset.timerClock!==undefined)lab.timer.channels[Number(el.dataset.timerClock)].clock=clamp(n,0,1e7);else if(id==='usb-inserted')scope.usbInserted=el.checked;else if(id==='trigger-width')scope.trigger.width=clamp(n,1e-9,50);else if(id==='trigger-holdoff')scope.trigger.holdoff=clamp(n,0,50);else if(id==='video-standard')scope.trigger.standard=el.value;else if(id==='video-line')scope.trigger.line=clamp(Math.round(n),1,625);else if(id==='math-scale')scope.math.scale=clamp(n,.001,1000);else if(id==='led-active-low')lab.activeLowLED=el.checked;lab.sync();refresh();}));
$('lcd-input').addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey){if(e.key.toLowerCase()==='v'||e.key.toLowerCase()==='c')return;e.preventDefault();return;}if(e.key==='Tab'){e.preventDefault();entryQueue=[];typeKey('Tab');return;}if(e.key.length===1||['Enter','Backspace','Delete','Escape','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();entryQueue=[];typeKey(e.key);}});
$('lcd-input').addEventListener('input',e=>{const value=e.target.value;if(value)for(const char of value)typeKey(char);e.target.value='';});
document.addEventListener('input',e=>{if(e.target.id==='student-id'&&/^\d{6}$/.test(e.target.value)){lab.id=e.target.value;const preview=experimentProgram(experiment,lab),pre=$('notebook-content').querySelector('pre'),note=$('notebook-content').querySelector('.manual-note');if(pre)pre.textContent=preview.instructions.map(r=>hex(r.address,4)+'  '+r.text).join('\n');if(note)note.textContent=`PA = ${lab.id.slice(0,2)}, PB = ${lab.id.slice(2,4)}, PC = ${lab.id.slice(4,6)} on the independent SC-01 8255. Values are packed BCD, with two groups of four LEDs per port.`;}});
$('lcd-input').addEventListener('paste',e=>{e.preventDefault();const text=e.clipboardData.getData('text/plain').replaceAll('\r\n','\n').replaceAll('\r','\n');if(text.length>20000){toast('Paste fewer than 20,000 characters at a time');return;}entryQueue=[...text].map(c=>c==='\n'?'Enter':c);entryDue=performance.now();toast('Pasted lines will be processed individually on the LCD');});
document.addEventListener('keydown',e=>{if(e.target===$('lcd-input'))return;if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;const knob=e.target.closest('[data-knob]');if(knob&&['ArrowUp','ArrowRight','ArrowDown','ArrowLeft'].includes(e.key)){e.preventDefault();turnKnob(knob.dataset.knob,e.key==='ArrowUp'||e.key==='ArrowRight'?1:-1,e.shiftKey);return;}if(e.key==='Escape')clearPending();if(e.key==='Delete'&&selectedWire)removeCable();if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button]')){e.preventDefault();e.target.click();}});
viewport.addEventListener('pointerdown',e=>{if(e.button!==0)return;const knob=e.target.closest('[data-knob]'),grip=e.target.closest('[data-move]');if(knob){e.preventDefault();drag={type:'knob',name:knob.dataset.knob,y:e.clientY,residual:0};}else if(grip&&!e.target.closest('button')){e.preventDefault();drag={type:'gear',id:grip.dataset.move,x:e.clientX,y:e.clientY};$('equipment-'+drag.id)?.classList.add('moving');}else if(!e.target.closest('button,input,select,[role=button],.wire-hit,.desk-welcome,.zoom-tools')){drag={type:'pan',x:e.clientX,y:e.clientY};viewport.classList.add('panning');}if(drag)viewport.setPointerCapture(e.pointerId);});
viewport.addEventListener('pointermove',e=>{if(pending){const a=endPosition(CONNECTORS[pending.id]?.prefix||pending.id,pending.type),b=world(e.clientX,e.clientY);if(a)$('pending-cable').innerHTML=`<path d="${wirePath(a,b)}" stroke="#e4d48a" stroke-width="3" stroke-dasharray="7 5" fill="none"/>`;}if(!drag)return;if(drag.type==='pan'){currentFocus=null;view.x+=e.clientX-drag.x;view.y+=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;updateView();}else if(drag.type==='gear'){const r=layout[drag.id];r.x=clamp(r.x+(e.clientX-drag.x)/view.scale,-500,2500);r.y=clamp(r.y+(e.clientY-drag.y)/view.scale,-200,2000);drag.x=e.clientX;drag.y=e.clientY;const el=$('equipment-'+drag.id);el.style.left=r.x+'px';el.style.top=r.y+'px';drawWires();}else{drag.residual+=(drag.y-e.clientY)/6;drag.y=e.clientY;const steps=Math.trunc(drag.residual);if(steps){drag.residual-=steps;guard(()=>turnKnob(drag.name,steps,e.shiftKey));}}});
function endDrag(){if(drag?.type==='gear')$('equipment-'+drag.id)?.classList.remove('moving');drag=null;viewport.classList.remove('panning');}
viewport.addEventListener('pointerup',endDrag);viewport.addEventListener('pointercancel',endDrag);viewport.addEventListener('dblclick',e=>{if(e.target.id==='tek-screen'){focus('scope-screen');return;}const gear=e.target.closest('[data-equipment]');if(gear&&!e.target.closest('button,input,[role=button]'))focus(gear.dataset.equipment);});
viewport.addEventListener('wheel',e=>{if(e.target.closest('.desk-welcome'))return;e.preventDefault();const knob=e.target.closest('[data-knob]');if(knob){guard(()=>turnKnob(knob.dataset.knob,e.deltaY<0?1:-1,e.shiftKey));}else{const r=viewport.getBoundingClientRect();zoom(Math.exp(-e.deltaY*.0014),e.clientX-r.left,e.clientY-r.top);}},{passive:false});
window.addEventListener('resize',()=>{const size={w:viewport.clientWidth,h:viewport.clientHeight};if(currentFocus)focus(currentFocus);else{view.x+=(size.w-lastSize.w)/2;view.y+=(size.h-lastSize.h)/2;updateView();drawWires();}lastSize=size;});
function animate(now){const elapsed=Math.min(.08,(now-lastFrame)/1000);lastFrame=now;if(!paused){if(monitor.running&&!(lab.studyBusConnected&&lab.studySingleStep))monitor.runSlice(30000,6,lab.time+elapsed*speed);else lab.tick(elapsed*speed*lab.clock);if(now>=entryDue&&entryQueue.length){try{if(entryQueue[0]==='Enter'){entryQueue.shift();monitor.key('Enter');entryDue=now+110;}else{while(entryQueue.length&&entryQueue[0]!=='Enter')monitor.key(entryQueue.shift());entryDue=now+330;}if(monitor.error)throw new Error(monitor.error);if(!entryQueue.length)toast('Every line entered. Reset, then G 2000 . to execute.');}catch(e){entryQueue=[];toast('LCD entry stopped: '+e.message);}}}
  if(now-lastUi>110){lastUi=now;refresh();renderTerminal();}requestAnimationFrame(animate);}
focus('all');refresh();requestAnimationFrame(()=>{drawWires();requestAnimationFrame(animate);});
